function validate([jobDifficulty, d]) {
  if (jobDifficulty.length < 1 || jobDifficulty.length > 300) return 'jobDifficulty needs 1 to 300 jobs.';
  if (jobDifficulty.some(v => !Number.isInteger(v) || v < 0 || v > 1000)) return 'Each difficulty is an integer from 0 to 1000.';
  if (!Number.isInteger(d) || d < 1 || d > 10) return 'd is between 1 and 10.';
  return null;
}

