function minDifficulty(jobDifficulty, d) {
  const n = jobDifficulty.length;
  if (n < d) {
    return -1;
  }

  const dp = Array.from({ length: d + 1 }, () => new Array(n + 1).fill(Infinity));
  dp[0][0] = 0;

  for (let day = 1; day <= d; day++) {
    for (let end = day; end <= n; end++) {
      let hardest = 0;
      for (let start = end - 1; start >= day - 1; start--) {
        hardest = Math.max(hardest, jobDifficulty[start]);
        dp[day][end] = Math.min(dp[day][end], dp[day - 1][start] + hardest);
      }
    }
  }
  return dp[d][n];
}

