function minDifficulty(jobDifficulty, d) {
  const n = jobDifficulty.length;
  if (n < d) return -1;
  // Enumerate every choice of d - 1 cut gaps; gap g means a new day starts at job g + 1.
  const cuts = Array.from({ length: d - 1 }, (_, i) => i);
  let best = Infinity;
  for (;;) {
    let total = 0, dayMax = 0, next = 0;
    for (let i = 0; i < n; i++) {
      dayMax = Math.max(dayMax, jobDifficulty[i]);
      if (i === n - 1 || (next < cuts.length && cuts[next] === i)) { total += dayMax; dayMax = 0; next++; }
    }
    best = Math.min(best, total);
    // Advance to the next combination of gaps from 0 to n - 2.
    let k = cuts.length - 1;
    while (k >= 0 && cuts[k] === n - 2 - (cuts.length - 1 - k)) k--;
    if (k < 0) return best;
    cuts[k]++;
    for (let j = k + 1; j < cuts.length; j++) cuts[j] = cuts[j - 1] + 1;
  }
}

