function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = int(1, 9);
    const top = rand() < 0.5 ? 6 : 1000;
    const jobs = Array.from({ length: n }, () => int(0, top));
    const d = rand() < 0.85 ? int(1, Math.min(n, 10)) : int(1, 10);
    return [jobs, d];
  }
  const n = rand() < 0.5 ? 300 : int(150, 300);
  const jobs = Array.from({ length: n }, () => int(0, 1000));
  return [jobs, int(1, 10)];
}
